// Randomly decide whether to request major/minor separately.
unsigned int want_major = (*FUZZ_PARAM(unsigned int)) & 1u;
unsigned int want_minor = (*FUZZ_PARAM(unsigned int)) & 1u;
unsigned int major = 0, minor = 0;
unsigned int *pmajor = want_major ? &major : NULL;
unsigned int *pminor = want_minor ? &minor : NULL;
// Call ks_version, which returns (major << 8) | minor.
unsigned int combined = ks_version(pmajor, pminor);
// If both requested, assert the documented packing property.
if (pmajor && pminor) {
    unsigned int expect = (major << 8) | minor;
    FUZZ_ASSERT(combined == expect, "ks_version combined value must equal (major<<8)|minor");
}
// Validation: Ensures NULL handling for optional outputs and validates packing when both pointers are provided.

// Choose a ks_arch in the valid enumerator range [1, KS_ARCH_MAX-1].
ks_arch arch = (ks_arch)(1 + ((*FUZZ_PARAM(unsigned int)) % (KS_ARCH_MAX - 1)));
// Query support. We do not assert, since support depends on build/runtime.
bool supported = ks_arch_supported(arch);
(void)supported;
// Validation: Uses a valid enum value and exercises both true/false paths depending on runtime support.

// Pick a candidate architecture in the valid range, then require it be supported.
ks_arch arch = (ks_arch)(1 + ((*FUZZ_PARAM(unsigned int)) % (KS_ARCH_MAX - 1)));
if (!ks_arch_supported(arch)) { FUZZ_BAIL(); }

// Pick a plausible mode combination per-arch. Randomize endianness when meaningful.
int be = (int)((*FUZZ_PARAM(unsigned int)) & 1u) ? KS_MODE_BIG_ENDIAN : KS_MODE_LITTLE_ENDIAN;
int mode = 0;
switch (arch) {
    case KS_ARCH_X86: {
        unsigned int sel = (*FUZZ_PARAM(unsigned int)) % 3u;
        mode = (sel == 0 ? KS_MODE_16 : sel == 1 ? KS_MODE_32 : KS_MODE_64);
        break;
    }
    case KS_ARCH_ARM: {
        unsigned int sel = (*FUZZ_PARAM(unsigned int)) & 1u;
        mode = (sel ? KS_MODE_ARM : KS_MODE_THUMB) | be;
        break;
    }
    case KS_ARCH_ARM64: {
        // AArch64 generally ignores mode flags, but allow V8/endian flags for coverage.
        mode = be | KS_MODE_V8;
        break;
    }
    case KS_ARCH_MIPS: {
        unsigned int sel = (*FUZZ_PARAM(unsigned int)) % 4u;
        mode = (sel == 0 ? KS_MODE_MIPS32 : sel == 1 ? KS_MODE_MIPS64 : sel == 2 ? KS_MODE_MIPS3 : KS_MODE_MIPS32R6) | be;
        break;
    }
    case KS_ARCH_SPARC: {
        unsigned int sel = (*FUZZ_PARAM(unsigned int)) & 1u;
        mode = (sel ? KS_MODE_SPARC32 : KS_MODE_SPARC64) | KS_MODE_V9 | be;
        break;
    }
    case KS_ARCH_RISCV: {
        unsigned int sel = (*FUZZ_PARAM(unsigned int)) & 1u;
        mode = (sel ? KS_MODE_RISCV32 : KS_MODE_RISCV64) | be;
        break;
    }
    case KS_ARCH_SYSTEMZ: {
        mode = be; // SystemZ is big-endian by spec; keep be to exercise path.
        break;
    }
    case KS_ARCH_HEXAGON: {
        mode = be;
        break;
    }
    case KS_ARCH_EVM: {
        mode = 0; // EVM has no mode flags.
        break;
    }
    default: {
        // Unsupported/unknown mode mapping for this arch.
        FUZZ_BAIL();
    }
}

ks_engine *ks = NULL;
ks_err err = ks_open(arch, mode, &ks);
if (err != KS_ERR_OK || !ks) { FUZZ_BAIL(); }
// Track arch/mode on the handle for downstream validation if needed.
FUZZ_SET_ATTR_INT(ks, "arch", (int)arch);
FUZZ_SET_ATTR_INT(ks, "mode", mode);
// Validation: Ensures arch is supported and mode is plausible per-arch; bails on failure, outputs a valid ks_engine*.

// Close a valid Keystone handle. After this, ks must not be reused.
ks_err err = ks_close(ks);
FUZZ_ASSERT(err == KS_ERR_OK, "ks_close should succeed for a valid handle");
// Validation: Ensures correct lifetime termination and asserts success for a valid handle; handle is not returned to the pool.

// Query last-error on a valid handle. This is safe regardless of prior failures.
ks_err last = ks_errno(ks);
(void)last;
// Validation: Preserves the handle (method call) and exercises the error retrieval path without altering lifetime.

// Choose a plausible ks_err code value in a small range.
ks_err code = (ks_err)((*FUZZ_PARAM(unsigned int)) % 64u);
const char *msg = ks_strerror(code);
FUZZ_ASSERT(msg != NULL, "ks_strerror must return a non-NULL pointer");
// The returned pointer is static/managed; do not free or modify.
// Validation: Asserts non-null returned string and avoids ownership violations.

// Randomly choose which option type to set.
ks_opt_type opt_type = ((*FUZZ_PARAM(unsigned int)) & 1u) ? KS_OPT_SYNTAX : KS_OPT_SYM_RESOLVER;
size_t value = 0;
if (opt_type == KS_OPT_SYNTAX) {
    // Choose a syntax flag; primarily affects X86 but is accepted cross-arch.
    unsigned int sel = (*FUZZ_PARAM(unsigned int)) % 6u;
    ks_opt_value syntax = (sel == 0 ? KS_OPT_SYNTAX_INTEL :
                           sel == 1 ? KS_OPT_SYNTAX_ATT :
                           sel == 2 ? KS_OPT_SYNTAX_NASM :
                           sel == 3 ? KS_OPT_SYNTAX_MASM :
                           sel == 4 ? KS_OPT_SYNTAX_GAS :
                                      KS_OPT_SYNTAX_RADIX16);
    value = (size_t)syntax;
} else {
    // Install a non-capturing lambda as symbol resolver; it converts to function pointer type.
    ks_sym_resolver resolver = +[](const char *symbol, uint64_t *out) -> bool {
        // Provide a simple deterministic mapping: hex parse or length.
        if (!symbol || !out) return false;
        // Use up to 16 hex digits if present; otherwise use string length as value.
        uint64_t v = 0;
        const char *s = symbol;
        bool any = false;
        while (*s) {
            char c = *s++;
            if (c >= '0' && c <= '9') { v = (v << 4) | (uint64_t)(c - '0'); any = true; }
            else if (c >= 'a' && c <= 'f') { v = (v << 4) | (uint64_t)(10 + c - 'a'); any = true; }
            else if (c >= 'A' && c <= 'F') { v = (v << 4) | (uint64_t)(10 + c - 'A'); any = true; }
        }
        if (!any) {
            // Fallback: use string length to produce a value.
            size_t len = 0; s = symbol; while (*s++) { ++len; }
            v = (uint64_t)len;
        }
        *out = v;
        return true;
    };
    value = (size_t)resolver;
}
ks_err rc = ks_option(ks, opt_type, value);
// Track successful configuration for downstream logic.
if (rc == KS_ERR_OK) {
    if (opt_type == KS_OPT_SYNTAX) {
        FUZZ_SET_ATTR_INT(ks, "has_syntax", 1);
    } else {
        FUZZ_SET_ATTR_INT(ks, "has_sym_resolver", 1);
    }
}
// Do not treat non-OK as fatal: invalid options are allowed by API contract.
// Validation: Maintains handle lifetime, sets either syntax or a safe resolver, and records state upon success.

// Prepare assembly input string; allow arbitrary bytes (nul-terminated via c_str()).
std::string asm_src = FUZZ_PARAM_STR();
const char *src_c = asm_src.c_str();
// Choose a random base address.
uint64_t address = (uint64_t)(*FUZZ_PARAM(unsigned long long));
// Outputs: encoding buffer (allocated on success), its size, and statement count.
unsigned char *encoding = NULL;
size_t encoding_size = 0;
size_t stat_count = 0;
int ret = ks_asm(ks, src_c, address, &encoding, &encoding_size, &stat_count);
if (ret == 0) {
    // Success path: encoding must be non-null and size > 0 per Keystone semantics.
    FUZZ_ASSERT(encoding != NULL, "ks_asm success must produce a non-NULL encoding buffer");
    FUZZ_ASSERT(encoding_size > 0, "ks_asm success must produce a non-zero encoding_size");
    // Free immediately to avoid leaks; do not return encoding to the object pool.
    ks_free(encoding);
    encoding = NULL;
} else {
    // Failure path: encoding untouched; optionally consult ks_errno(ks) for side effects.
    (void)ks_errno(ks);
}
// Validation: Enforces non-null outputs on success and frees with ks_free; preserves handle for reuse.

// Create an engine and assemble a trivial instruction to obtain a buffer to free.
// Prefer X86 as it is commonly available; bail if unsupported.
if (!ks_arch_supported(KS_ARCH_X86)) { FUZZ_BAIL(); }
ks_engine *ks = NULL;
ks_err err = ks_open(KS_ARCH_X86, KS_MODE_64, &ks);
if (err != KS_ERR_OK || !ks) { FUZZ_BAIL(); }
// Assemble a simple instruction that should succeed on x86-64.
const char *src = "nop";
unsigned char *encoding = NULL;
size_t encoding_size = 0;
size_t stat_count = 0;
int ret = ks_asm(ks, src, 0, &encoding, &encoding_size, &stat_count);
if (ret != 0 || !encoding || encoding_size == 0) {
    // Clean up engine and bail if we could not obtain a valid buffer per API requirements.
    (void)ks_close(ks);
    FUZZ_BAIL();
}
// Now invoke the target function under correct preconditions.
ks_free(encoding);
encoding = NULL;
// Cleanup engine handle.
(void)ks_close(ks);
// Validation: Guarantees ks_free is called with a buffer allocated by ks_asm and avoids leaks; handles engine lifecycle safely.

