import random
import struct
from typing import List, Tuple

# This generator produces valid assembly source buffers (null-terminated via C++ std::string)
# intended for Keystone ks_asm fuzzers. It focuses on x86/x64 Intel syntax as a broadly
# supported default, and randomly mixes short, medium, and richer programs including labels,
# directives, immediates, memory operands, jumps/calls, and data definitions.
# The output is UTF-8 text bytes (<=4096 bytes) suitable for FUZZ_PARAM_STR.

REG8 = ["al","cl","dl","bl","ah","ch","dh","bh","spl","bpl","sil","dil","r8b","r9b","r10b","r11b","r12b","r13b","r14b","r15b"]
REG16 = ["ax","cx","dx","bx","sp","bp","si","di","r8w","r9w","r10w","r11w","r12w","r13w","r14w","r15w"]
REG32 = ["eax","ecx","edx","ebx","esp","ebp","esi","edi","r8d","r9d","r10d","r11d","r12d","r13d","r14d","r15d"]
REG64 = ["rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15"]
SEG = ["cs","ds","es","fs","gs","ss"]
SSE = ["xmm0","xmm1","xmm2","xmm3","xmm4","xmm5","xmm6","xmm7","xmm8","xmm9","xmm10","xmm11","xmm12","xmm13","xmm14","xmm15"]

MNEMONICS0 = [
    "nop","cpuid","hlt","leave","cwd","cdq","cqo","stc","clc","cmc","std","cld","wait"
]
MNEMONICS_UNARY = [
    "inc","dec","neg","not","push","pop","bswap","setnz","setz","sete","setne"
]
MNEMONICS_MOV = ["mov","lea","cmovz","cmovne","movzx","movsx","xchg"]
MNEMONICS_BIN = ["add","sub","imul","xor","or","and","adc","sbb","cmp","test","shl","shr","sal","sar"]
MNEMONICS_JMP = ["jmp","je","jne","jg","jl","jge","jle","ja","jb","call"]

# Simple label names
LABELS = ["start","loop","exit","L1","L2","L3","done","continue","func","target"]

DIRECTIVES = [
    ("db", lambda r: ", ".join(str(random.randint(0,255)) for _ in range(r.randint(1,8)))),
    ("dw", lambda r: ", ".join(str(random.randint(0,65535)) for _ in range(r.randint(1,6)))),
    ("dd", lambda r: ", ".join(str(random.randint(0,0xffffffff)) for _ in range(r.randint(1,4)))),
    ("dq", lambda r: ", ".join(str(random.randint(0,0xffffffffffffffff)) for _ in range(r.randint(1,3)))),
]

SCALES = [1,2,4,8]

def rchoice(r: random.Random, seq: List[str]):
    return seq[r.randrange(len(seq))]

def imm(r: random.Random) -> str:
    # mix small, large, hex, negative
    kind = r.randrange(5)
    if kind == 0:
        return str(r.randint(0, 127))
    if kind == 1:
        return str(r.randint(-128, 127))
    if kind == 2:
        return hex(r.randint(0, 0xffffffff))
    if kind == 3:
        return hex(r.randint(0, 0xffff))
    return str(r.randint(0, 0xffffffffffffffff))

def mem_operand(r: random.Random, bits: int) -> str:
    # [base + index*scale + disp], optional segment
    base = rchoice(r, REG64 if bits==64 else REG32)
    use_index = r.random() < 0.7
    parts = []
    if r.random() < 0.15:
        seg = rchoice(r, SEG)
        parts.append(seg + ":")
    expr = "[" + base
    if use_index:
        idx = rchoice(r, REG64 if bits==64 else REG32)
        scale = rchoice(r, SCALES)
        expr += f" + {idx}*{scale}"
    if r.random() < 0.7:
        disp = r.randint(-0x800, 0x7fff)
        if disp >= 0:
            expr += f" + {disp}"
        else:
            expr += f" - {abs(disp)}"
    expr += "]"
    parts.append(expr)
    return "".join(parts)

def reg_by_size(r: random.Random, bits: int, size: int) -> str:
    if size == 8:
        return rchoice(r, REG8)
    if size == 16:
        return rchoice(r, REG16)
    if size == 32:
        return rchoice(r, REG32)
    return rchoice(r, REG64 if bits==64 else REG32)

def make_unary(r: random.Random, bits: int) -> str:
    mnem = rchoice(r, MNEMONICS_UNARY)
    if mnem in ("push","pop"):
        op = reg_by_size(r, bits, 64 if bits==64 else 32)
    elif mnem == "bswap":
        op = reg_by_size(r, bits, 32 if r.random()<0.5 else 64)
    else:
        size = rchoice(r, [8,16,32,64]) if bits==64 else rchoice(r,[8,16,32])
        if r.random() < 0.5:
            op = reg_by_size(r, bits, size)
        else:
            op = mem_operand(r, bits)
    return f"{mnem} {op}"

def make_mov(r: random.Random, bits: int) -> str:
    mnem = rchoice(r, MNEMONICS_MOV)
    if mnem == "lea":
        dst = reg_by_size(r, bits, 64 if bits==64 else 32)
        src = mem_operand(r, bits)
    elif mnem in ("movzx","movsx"):
        dst = reg_by_size(r, bits, 32 if bits==64 else 16)
        src = reg_by_size(r, bits, 8 if r.random()<0.5 else 16)
    elif mnem == "xchg":
        dst = reg_by_size(r, bits, rchoice(r,[8,16,32,64]) if bits==64 else rchoice(r,[8,16,32]))
        src = reg_by_size(r, bits, 64 if bits==64 else 32)
    else:
        size = rchoice(r, [8,16,32,64]) if bits==64 else rchoice(r,[8,16,32])
        dst = reg_by_size(r, bits, size)
        if r.random() < 0.4:
            src = mem_operand(r, bits)
        elif r.random() < 0.5:
            src = imm(r)
        else:
            src = reg_by_size(r, bits, size)
    return f"{mnem} {dst}, {src}"

def make_bin(r: random.Random, bits: int) -> str:
    mnem = rchoice(r, MNEMONICS_BIN)
    size = rchoice(r, [8,16,32,64]) if bits==64 else rchoice(r,[8,16,32])
    dst_is_mem = r.random() < 0.3
    dst = mem_operand(r, bits) if dst_is_mem else reg_by_size(r, bits, size)
    src_choice = r.random()
    if src_choice < 0.33:
        src = reg_by_size(r, bits, size)
    elif src_choice < 0.66:
        src = imm(r)
    else:
        src = mem_operand(r, bits)
    return f"{mnem} {dst}, {src}"

def make_jump(r: random.Random) -> str:
    mnem = rchoice(r, MNEMONICS_JMP)
    label = rchoice(r, LABELS)
    return f"{mnem} {label}"

def make_zeroop(r: random.Random) -> str:
    return rchoice(r, MNEMONICS0)

def make_sse(r: random.Random, bits: int) -> str:
    mnem = rchoice(r, ["movdqa","movdqu","pxor","paddq","psubq","movq"])
    dst = rchoice(r, SSE)
    if r.random() < 0.5:
        src = rchoice(r, SSE)
    else:
        src = mem_operand(r, bits)
    return f"{mnem} {dst}, {src}"

def make_directive(r: random.Random) -> str:
    name, gen = rchoice(r, DIRECTIVES)
    return f".{name} {gen(r)}"

def program_templates(r: random.Random, bits: int) -> List[str]:
    lines: List[str] = []
    # Optional syntax note for Intel (Keystone defaults to Intel for x86, but include for clarity)
    if r.random() < 0.2:
        lines.append("; x86-64 Intel syntax")
    # Prologue
    if bits == 64 and r.random() < 0.7:
        lines += [
            "push rbp",
            "mov rbp, rsp",
            f"sub rsp, {16 * r.randint(0,4)}",
        ]
    # Some labels and flows
    used_labels = r.sample(LABELS, k=r.randint(2, 4))
    for lb in used_labels:
        lines.append(f"{lb}:")
        # block content
        for _ in range(r.randint(2, 6)):
            choice = r.random()
            if choice < 0.15:
                lines.append(make_zeroop(r))
            elif choice < 0.35:
                lines.append(make_unary(r, bits))
            elif choice < 0.65:
                lines.append(make_mov(r, bits))
            elif choice < 0.9:
                lines.append(make_bin(r, bits))
            else:
                lines.append(make_sse(r, bits))
        # occasional local data
        if r.random() < 0.3:
            lines.append(make_directive(r))
        # a jump to another label
        if r.random() < 0.7:
            lines.append(make_jump(r))
    # Epilogue
    if bits == 64 and r.random() < 0.8:
        lines += [
            "mov rsp, rbp",
            "pop rbp",
            "ret",
        ]
    else:
        if r.random() < 0.5:
            lines.append("ret")
    return lines

def small_snippet(r: random.Random, bits: int) -> List[str]:
    lines = []
    n = r.randint(1, 6)
    for _ in range(n):
        choice = r.random()
        if choice < 0.2:
            lines.append(make_zeroop(r))
        elif choice < 0.45:
            lines.append(make_unary(r, bits))
        elif choice < 0.75:
            lines.append(make_mov(r, bits))
        else:
            lines.append(make_bin(r, bits))
    return lines

def header_directives(r: random.Random, bits: int) -> List[str]:
    lines: List[str] = []
    # Mix of alignment and data. Keystone supports some directives via backends; use simple ones.
    if r.random() < 0.3:
        lines.append("align 16")
    if r.random() < 0.4:
        lines.append(make_directive(r))
    # Global label
    if r.random() < 0.5:
        lines.append("global start")
        lines.append("start:")
    return lines

def build_program(r: random.Random) -> str:
    # Choose 32-bit or 64-bit x86; Keystone defaults for x86 mode are architecture dependent,
    # but both are widely supported. We bias toward 64-bit for coverage.
    bits = 64 if r.random() < 0.7 else 32
    sections: List[str] = []
    sections += header_directives(r, bits)
    # Compose either a small snippet or a template program
    if r.random() < 0.5:
        sections += small_snippet(r, bits)
    else:
        sections += program_templates(r, bits)
    # Ensure there is at least one label target for jumps
    if not any(line.endswith(":") for line in sections):
        sections.insert(0, "entry:")
        if r.random() < 0.5:
            sections.append("jmp entry")
    # Join with newlines; semicolons work too, but newlines are clearer
    text = "\n".join(sections) + "\n"
    # Cap size to 4096 bytes by trimming trailing content if necessary
    if len(text.encode("utf-8")) > 4096:
        # Keep first 4000 bytes roughly
        enc = text.encode("utf-8")[:4000]
        # Ensure ends with newline
        if not enc.endswith(b"\n"):
            enc += b"\n"
        return enc.decode("utf-8", errors="ignore")
    return text

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Generate between 1 and 3 concatenated programs separated by blank lines to exercise
    # multi-statement parsing
    pieces = []
    for _ in range(1 + r.randrange(3)):
        pieces.append(build_program(r))
    src = "\n".join(pieces)
    # Ensure within 4096 bytes
    b = src.encode("utf-8")
    if len(b) > 4096:
        b = b[:4096]
        # make sure it ends with a newline to avoid cutting tokens mid-line in many cases
        if not b.endswith(b"\n"):
            b = b.rstrip(b"\r\n") + b"\n"
    return b
